/**
 * controllers/bookController.js
 * Business logic for the books resource.
 *
 * Books are kept in a temporary in-memory array (no database yet), so
 * any books added with POST are lost when the server restarts.
 *
 * Each book has six attributes:
 *   id     - unique identifier (b1, b2, ...), generated by the server
 *   title  - book title
 *   author - author's name
 *   genre  - genre, for example Fiction or Technology
 *   year   - year the book was published
 *   price  - price in South African rand (ZAR)
 */

// Temporary in-memory data store with three starting books
const books = [
  {
    id: 'b1',
    title: 'Clean Code',
    author: 'Robert C. Martin',
    genre: 'Technology',
    year: 2008,
    price: 650,
  },
  {
    id: 'b2',
    title: 'Long Walk to Freedom',
    author: 'Nelson Mandela',
    genre: 'Biography',
    year: 1994,
    price: 320,
  },
  {
    id: 'b3',
    title: 'Things Fall Apart',
    author: 'Chinua Achebe',
    genre: 'Fiction',
    year: 1958,
    price: 210,
  },
];

// Counter used to build the next id (b4, b5, ...)
let nextId = books.length + 1;

/**
 * GET /api/books
 * Returns all books and how many there are.
 */
const getAllBooks = (req, res) => {
  res.status(200).json({
    count: books.length,
    data: books,
  });
};

/**
 * GET /api/books/:id
 * Returns a single book. If no book has that id, a 404 error is passed
 * to the central error handler.
 */
const getBookById = (req, res, next) => {
  const id = req.params.id.toLowerCase();
  const book = books.find((b) => b.id === id);

  if (!book) {
    const error = new Error(`Book with id '${req.params.id}' was not found`);
    error.statusCode = 404;
    return next(error);
  }

  return res.status(200).json({ data: book });
};

/**
 * POST /api/books
 * Adds a new book. The body has already been checked by
 * validateBookInput, so only clean values reach this function.
 * The server creates the id so clients cannot overwrite existing books.
 */
const createBook = (req, res) => {
  const { title, author, genre, year, price } = req.body;

  const newBook = {
    id: `b${nextId}`,
    title: title.trim(),
    author: author.trim(),
    genre: genre.trim(),
    year: Number(year),
    price: Number(price),
  };

  nextId += 1;
  books.push(newBook);

  res.status(201).json({
    message: 'Book added successfully',
    data: newBook,
  });
};

module.exports = {
  getAllBooks,
  getBookById,
  createBook,
};
